import "server-only";
import fs from "node:fs";
import path from "node:path";
import type { Workspace } from "@/lib/domain/types";
import { writeFileAtomic } from "@/lib/store/data-file";
import { DATA_DIR } from "@/lib/store/settings";

/**
 * Studio's binary files (uploaded screenshots, generated images, designs and their renders) live
 * in `.data/studio/`, next to the workspace and never in it. Names are generated by code and
 * checked against a strict pattern before any read or write, so a request can't reach other files.
 */

export const STUDIO_DIR = path.join(DATA_DIR, "studio");
const SAFE_NAME = /^[a-z]{2,6}_[A-Za-z0-9]{6,40}\.(png|jpg|svg)$/;

export function isSafeName(name: string): boolean {
  return SAFE_NAME.test(name);
}

export function saveStudioFile(name: string, data: Buffer | string): void {
  if (!isSafeName(name)) throw new Error(`Unsafe file name: ${name}`);
  writeFileAtomic(path.join(STUDIO_DIR, name), data);
}

export function readStudioFile(name: string): Buffer | null {
  if (!isSafeName(name)) return null;
  try {
    return fs.readFileSync(path.join(STUDIO_DIR, name));
  } catch {
    return null;
  }
}

export function removeStudioFile(name: string): void {
  if (!isSafeName(name)) return;
  fs.rmSync(path.join(STUDIO_DIR, name), { force: true });
}

/**
 * Deletes files no image or graphic refers to any more (after the founder removes them). Files
 * younger than 10 minutes stay: a run may have written them and not saved its records yet.
 */
export function sweepStudioFiles(ws: Workspace, now = Date.now()): number {
  let names: string[];
  try {
    names = fs.readdirSync(STUDIO_DIR);
  } catch {
    return 0;
  }
  const used = new Set<string>();
  for (const i of Object.values(ws.studio.images)) used.add(i.file);
  for (const v of Object.values(ws.studio.visuals)) {
    used.add(v.svgFile);
    if (v.pngFile) used.add(v.pngFile);
  }
  let removed = 0;
  for (const name of names) {
    if (!isSafeName(name) || used.has(name)) continue;
    try {
      if (now - fs.statSync(path.join(STUDIO_DIR, name)).mtimeMs < 10 * 60_000) continue;
      fs.rmSync(path.join(STUDIO_DIR, name), { force: true });
      removed++;
    } catch {
      // Gone already.
    }
  }
  return removed;
}

/** Width and height from a PNG or JPEG header, and which it is; null for anything else. */
export function imageInfo(buf: Buffer): { mime: "image/png" | "image/jpeg"; width: number; height: number } | null {
  if (buf.length > 24 && buf.readUInt32BE(0) === 0x89504e47 && buf.readUInt32BE(4) === 0x0d0a1a0a) {
    return { mime: "image/png", width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
  }
  if (buf.length > 4 && buf[0] === 0xff && buf[1] === 0xd8) {
    let i = 2;
    while (i + 9 < buf.length) {
      if (buf[i] !== 0xff) {
        i++;
        continue;
      }
      const marker = buf[i + 1];
      const len = buf.readUInt16BE(i + 2);
      // SOF0–SOF15 except DHT (C4), JPG (C8) and DAC (CC) carry the frame size.
      if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
        return { mime: "image/jpeg", height: buf.readUInt16BE(i + 5), width: buf.readUInt16BE(i + 7) };
      }
      i += 2 + len;
    }
  }
  return null;
}
